package com.leetcode.backend.model;
import jakarta.persistence.*;
@Entity @Table(name="contest_problems",uniqueConstraints={@UniqueConstraint(columnNames={"contest_id","problem_id"}),@UniqueConstraint(columnNames={"contest_id","display_order"})}) public class ContestProblem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="contest_id",nullable=false) private Contest contest; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="problem_id",nullable=false) private Problem problem; @Column(name="display_order",nullable=false) private int displayOrder; @Column(nullable=false) private int points=100; public Long getId(){return id;} public Contest getContest(){return contest;} public void setContest(Contest v){contest=v;} public Problem getProblem(){return problem;} public void setProblem(Problem v){problem=v;} public int getDisplayOrder(){return displayOrder;} public void setDisplayOrder(int v){displayOrder=v;} public int getPoints(){return points;} public void setPoints(int v){points=v;} }
